INSERT INTO markets_commodities (id, name, scope_note, season_basis, seasons, default_season, default_country, codes, valuation_methods, structure, gap_sources, crm, sort_order) VALUES ('banana', 'Bananas', 'Fresh bananas; some national series include plantains', 'FAOSTAT calendar year. Australian figures for 2024/25 are mapped to 2024.', '["2000","2010","2020","2023","2024"]'::jsonb, '2024', 'ECU', '[{"scheme":"FAO item","code":"486"},{"scheme":"HS","code":"0803"}]'::jsonb, '[{"id":"global_us","label":"Global price (US import)","price_series":"wb_banana_us","description":"Every country''s output valued at the World Bank US import price for that season.","caveat":"An import price at destination port. It includes shipping and overstates farm-gate value, most for domestic-market growers."},{"id":"global_eu","label":"Global price (EU import)","price_series":"wb_banana_eu","description":"Every country''s output valued at the World Bank EU import price for that season.","caveat":"An import price at destination port; overstates farm-gate value."},{"id":"local","label":"Local producer price","price_measure":"producer_price","description":"Each country''s output valued at its own farm-gate price, converted to USD.","caveat":"Most FAO producer prices in this sample are 2014-2018; where the price year differs from the season, the value is flagged."}]'::jsonb, '{"AUS":{"note":"About 500 farms, most family-run. The largest, the family-owned Mackay Farming Group, grows about 13% of national output across 9 farms.","classifications":{"area_size":["part","Not published by ABGC"],"turnover":["part","ABS value-of-operations bands available"],"ownership":["ok","Mostly family"]},"breakdowns":[{"label":"Share of national output","parts":[{"label":"Mackay Farming Group","share":0.13},{"label":"Other ~499 farms","share":0.87}]}],"sources":["abgc","jll"]},"ECU":{"note":"About 5,000 small producers hold roughly 30% of plantations and sell through cooperatives to exporters; large, technically advanced growers supply most exports. Los Ríos, El Oro and Guayas held 91% of commercial area in 2009.","classifications":{"area_size":["part","Small growers ≈30% of plantation area"],"turnover":["gap","No data"],"ownership":["part","Large exporters dominate"]},"breakdowns":[{"label":"Plantation area by grower size (c. 2009-13)","parts":[{"label":"~5,000 small producers","share":0.3},{"label":"Medium and large","share":0.7}]}],"sources":["promusa_ec"]},"PHL":{"note":"Export Cavendish comes from commercial plantations, from 2-20 ha monocrops up to multinational estates; smallholders mostly grow Saba and Lakatan for local markets. Mindanao held 99% of Cavendish in 2018.","classifications":{"area_size":["part","2-20 ha small plantations named"],"turnover":["gap","No data"],"ownership":["part","Corporate for export, family for local"]},"breakdowns":[],"sources":["promusa_ph"]},"IND":{"note":"State production is available. Farm counts by size and ownership need the Agriculture Census or Horticulture Statistics tables.","classifications":{"area_size":["gap","Needs Agriculture Census"],"turnover":["gap","No data"],"ownership":["gap","No data"]},"breakdowns":[],"sources":["ceic_nhb"]}}'::jsonb, '{"PHL":{"regions":"PSA Major Fruit Crops regional tables"},"ECU":{"regions":"MAG / ESPAC provincial data"},"_default":{"regions":"National agricultural statistics office","operators":"Certification and export registries","structure":"National agricultural census"}}'::jsonb, '{"id_prefix":"NH-BAN-","industry_label":"Agriculture / Bananas"}'::jsonb, 0)
INSERT INTO markets_commodities (id, name, scope_note, season_basis, seasons, default_season, default_country, codes, valuation_methods, structure, gap_sources, crm, sort_order) VALUES ('mango', 'Mangoes', 'Mangoes, mangosteens and guavas, as FAO and HS group them', 'FAOSTAT calendar year. Australian figures for 2020/21 are mapped to 2020.', '["2020","2023","2024"]'::jsonb, '2024', 'MEX', '[{"scheme":"FAO item","code":"571"},{"scheme":"HS","code":"080450"}]'::jsonb, '[{"id":"global","label":"World export price","price_series":"mango_world_export","description":"Every country''s output valued at the world average mango export price for that season.","caveat":"An export (FOB) price for traded fruit. It overstates the value of fruit sold on local markets, which is most mango output."},{"id":"local","label":"Local producer price","price_measure":"producer_price","description":"Each country''s output valued at its own farm-gate price, converted to USD.","caveat":"No mango producer prices are in this sample yet."}]'::jsonb, '{"AUS":{"note":"The Northern Territory grew 54% of the 2020/21 crop and Queensland 43%. NT output reached 4.3 million trays in 2025-26 from about 6,350 ha, with Darwin and Katherine the two regions. Grower numbers are not in this sample.","classifications":{"area_size":["part","NT area total only"],"turnover":["gap","No data"],"ownership":["gap","No data"]},"breakdowns":[{"label":"Production by state, 2020/21","parts":[{"label":"Northern Territory","share":0.54},{"label":"Queensland","share":0.43},{"label":"WA and NSW","share":0.03}]}],"sources":["hort_mango","arrn_nt"]},"IND":{"note":"Uttar Pradesh and Andhra Pradesh grow about 40% of India''s mangoes. Most fruit is sold fresh at home or processed into pulp; farm counts by size and ownership need the Agriculture Census.","classifications":{"area_size":["gap","Needs Agriculture Census"],"turnover":["gap","No data"],"ownership":["gap","No data"]},"breakdowns":[],"sources":["ceic_mango"]}}'::jsonb, '{"MEX":{"regions":"SIAP state production tables"},"PAK":{"regions":"Pakistan Bureau of Statistics fruit tables"}}'::jsonb, '{"id_prefix":"NH-MAN-","industry_label":"Agriculture / Mangoes"}'::jsonb, 1)
