INSERT INTO markets_structure (commodity, geo, note, classifications, breakdowns, sources) VALUES ('banana', 'AUS', 'About 500 farms, most family-run. The largest, the family-owned Mackay Farming Group, grows about 13% of national output across 9 farms.', '{"area_size":["part","Not published by ABGC"],"turnover":["part","ABS value-of-operations bands available"],"ownership":["ok","Mostly family"]}'::jsonb, '[{"label":"Share of national output","parts":[{"label":"Mackay Farming Group","share":0.13},{"label":"Other ~499 farms","share":0.87}]}]'::jsonb, '["abgc","jll"]'::jsonb)
INSERT INTO markets_structure (commodity, geo, note, classifications, breakdowns, sources) VALUES ('banana', 'ECU', 'About 5,000 small producers hold roughly 30% of plantations and sell through cooperatives to exporters; large, technically advanced growers supply most exports. Los Ríos, El Oro and Guayas held 91% of commercial area in 2009.', '{"area_size":["part","Small growers ≈30% of plantation area"],"turnover":["gap","No data"],"ownership":["part","Large exporters dominate"]}'::jsonb, '[{"label":"Plantation area by grower size (c. 2009-13)","parts":[{"label":"~5,000 small producers","share":0.3},{"label":"Medium and large","share":0.7}]}]'::jsonb, '["promusa_ec"]'::jsonb)
INSERT INTO markets_structure (commodity, geo, note, classifications, breakdowns, sources) VALUES ('banana', 'PHL', 'Export Cavendish comes from commercial plantations, from 2-20 ha monocrops up to multinational estates; smallholders mostly grow Saba and Lakatan for local markets. Mindanao held 99% of Cavendish in 2018.', '{"area_size":["part","2-20 ha small plantations named"],"turnover":["gap","No data"],"ownership":["part","Corporate for export, family for local"]}'::jsonb, '[]'::jsonb, '["promusa_ph"]'::jsonb)
INSERT INTO markets_structure (commodity, geo, note, classifications, breakdowns, sources) VALUES ('banana', 'IND', 'State production is available. Farm counts by size and ownership need the Agriculture Census or Horticulture Statistics tables.', '{"area_size":["gap","Needs Agriculture Census"],"turnover":["gap","No data"],"ownership":["gap","No data"]}'::jsonb, '[]'::jsonb, '["ceic_nhb"]'::jsonb)
INSERT INTO markets_structure (commodity, geo, note, classifications, breakdowns, sources) VALUES ('mango', 'AUS', 'The Northern Territory grew 54% of the 2020/21 crop and Queensland 43%. NT output reached 4.3 million trays in 2025-26 from about 6,350 ha, with Darwin and Katherine the two regions. Grower numbers are not in this sample.', '{"area_size":["part","NT area total only"],"turnover":["gap","No data"],"ownership":["gap","No data"]}'::jsonb, '[{"label":"Production by state, 2020/21","parts":[{"label":"Northern Territory","share":0.54},{"label":"Queensland","share":0.43},{"label":"WA and NSW","share":0.03}]}]'::jsonb, '["hort_mango","arrn_nt"]'::jsonb)
INSERT INTO markets_structure (commodity, geo, note, classifications, breakdowns, sources) VALUES ('mango', 'IND', 'Uttar Pradesh and Andhra Pradesh grow about 40% of India''s mangoes. Most fruit is sold fresh at home or processed into pulp; farm counts by size and ownership need the Agriculture Census.', '{"area_size":["gap","Needs Agriculture Census"],"turnover":["gap","No data"],"ownership":["gap","No data"]}'::jsonb, '[]'::jsonb, '["ceic_mango"]'::jsonb)
